// Auto-generated embedded B Nazanin WOFF2 font (base64) for 100% offline & PDF support
export const B_NAZANIN_WOFF2_BASE64 = "";

export function buildBNazaninFontFaceCss(): string {
  const dataUri = `data:font/woff2;base64,${B_NAZANIN_WOFF2_BASE64}`;
  const families = ["B Nazanin", "BNazanin", "B-Nazanin", "Nazanin"];
  const rules: string[] = [];

  for (const family of families) {
    for (const weight of ["normal", "bold", "400", "700"]) {
      rules.push(`@font-face {
  font-family: "${family}";
  src: url("${dataUri}") format("woff2"), url("/fonts/BNazanin.woff2") format("woff2"), url("/fonts/BNazanin.woff") format("woff"), url("/fonts/BNazanin.ttf") format("truetype");
  font-weight: ${weight};
  font-style: normal;
  font-display: block;
}`);
    }
  }

  // Unicode-ranged Persian font-face so Farsi characters always render in B Nazanin even inside mixed-language elements
  for (const weight of ["normal", "bold", "100 900"]) {
    rules.push(`@font-face {
  font-family: "RotoscopePersianBNazanin";
  src: url("${dataUri}") format("woff2"), url("/fonts/BNazanin.woff2") format("woff2"), url("/fonts/BNazanin.ttf") format("truetype");
  font-weight: ${weight};
  font-style: normal;
  font-display: block;
  unicode-range: U+0600-06FF, U+0750-077F, U+08A0-08FF, U+FB50-FDFF, U+FE70-FEFF, U+200C-200F;
}`);
  }

  return rules.join("\n");
}
